describe('File Upload - Invalid File Type Error', () => {
  beforeEach(() => {
    cy.visit('/file-upload');
  });

  it('should display error message when uploading an invalid file type', () => {
    // Intercept the file upload API call
    cy.intercept('POST', '/api/upload', {
      statusCode: 200,
      body: {
        success: false,
        error: 'Invalid file type. Only PDF and DOCX are allowed.'
      }
    }).as('uploadFile');

    // Attempt to upload an invalid file type (e.g., .txt)
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/invalid-file.txt', { force: true });

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Invalid file type');

    // Verify success button is disabled
    cy.get('[data-testid="upload-button"]').should('be.disabled');

    // Verify file input is cleared
    cy.get('[data-testid="file-input"]').should('have.value', '');

    // Verify error toast is visible
    cy.get('[data-testid="error-toast"]').should('be.visible');
    cy.get('[data-testid="error-toast"]').should('contain', 'File upload failed');

    // Verify error toast has correct message
    cy.get('[data-testid="error-toast"]').should('contain', 'Invalid file type');

    // Verify retry button is available
    cy.get('[data-testid="retry-button"]').should('be.visible');
  });

  it('should handle multiple invalid file types in a row', () => {
    // Intercept the file upload API call
    cy.intercept('POST', '/api/upload', {
      statusCode: 200,
      body: {
        success: false,
        error: 'Invalid file type. Only PDF and DOCX are allowed.'
      }
    }).as('uploadFile');

    // Attempt to upload multiple invalid file types
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/invalid-file.txt', { force: true });
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/invalid-file.docx', { force: true });
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/invalid-file.jpg', { force: true });

    // Verify error message is displayed for each file
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Invalid file type');

    // Verify success button remains disabled
    cy.get('[data-testid="upload-button"]').should('be.disabled');

    // Verify file input is cleared after each attempt
    cy.get('[data-testid="file-input"]').should('have.value', '');

    // Verify error toast is visible and contains all error messages
    cy.get('[data-testid="error-toast"]').should('be.visible');
    cy.get('[data-testid="error-toast"]').should('contain', 'File upload failed');
    cy.get('[data-testid="error-toast"]').should('contain', 'Invalid file type');

    // Verify retry button is available
    cy.get('[data-testid="retry-button"]').should('be.visible');
  });
});
